<?php
require __DIR__.'/common.php';
$db=authDb();$setup=(int)$db->query('SELECT COUNT(*) FROM accounts')->fetchColumn()===0;$mode=$_GET['mode']??'login';$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST')try{checkCsrf();$action=$_POST['action']??'';$username=trim($_POST['username']??'');$password=$_POST['password']??'';
if($action==='login'){ $q=$db->prepare('SELECT * FROM accounts WHERE username=?');$q->execute([$username]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u || !$u['active'] || !password_verify($password,$u['password_hash']))throw new Exception('Incorrect credentials or account not yet active.');session_regenerate_id(true);$_SESSION['user_id']=$u['id'];header('Location: ../index.php');exit; }
if($action==='register' || $action==='setup'){if($action==='setup' && !$setup)throw new Exception('Setup is already complete.');$name=trim($_POST['display_name']??'');if(strlen($username)<3||strlen($password)<10||$name==='')throw new Exception('Enter a name, username of at least 3 characters, and password of at least 10 characters.');$q=$db->prepare('INSERT INTO accounts(username,display_name,password_hash,role,active) VALUES(?,?,?,?,?)');$q->execute([$username,$name,password_hash($password,PASSWORD_DEFAULT),$action==='setup'?'superadmin':'staff',$action==='setup'?1:0]);$message=$action==='setup'?'Super administrator created. Sign in.':'Registration submitted. A super administrator must activate your account.';$setup=false;$mode='login';}
if($action==='forgot'){if($username!==''){$q=$db->prepare('UPDATE accounts SET reset_requested=1 WHERE username=?');$q->execute([$username]);}$message='If the account exists, a reset request has been sent to the local administrator. Contact them to reset your password.';$mode='login';}
}catch(Throwable $e){$error=$e instanceof PDOException?'That username is unavailable.':$e->getMessage();$mode=$_POST['action']??$mode;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in | Inventory Management System</title><link rel="stylesheet" href="../frontend/style.css"></head><body class="authbody"><main class="authlayout"><div class="authintro"><span class="brandmark">✳</span><h1>Inventory Management System</h1><p>Manage assets, supplies, and subscriptions in one workspace.</p></div><section class="authcard"><h2><?= $setup?'Set up super administrator':($mode==='register'?'Request an account':($mode==='forgot'?'Forgot password':'Sign in')) ?></h2><?php if($error):?><div class="notice error"><?=esc($error)?></div><?php endif;?><?php if($message):?><div class="notice"><?=esc($message)?></div><?php endif;?><form method="post" class="authform"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="action" value="<?= $setup?'setup':esc($mode) ?>"><?php if($setup||$mode==='register'):?><label>Full name<input name="display_name" required autocomplete="name"></label><?php endif;?><label>Username<input name="username" required autocomplete="username"></label><?php if($mode!=='forgot'||$setup):?><label>Password<input name="password" type="password" required autocomplete="<?= $setup||$mode==='register'?'new-password':'current-password' ?>" <?= $setup||$mode==='register'?'minlength="10"':'' ?>></label><?php endif;?><button class="button primary"><?= $setup?'Create super administrator':($mode==='register'?'Request account':($mode==='forgot'?'Request reset':'Sign in')) ?></button></form><?php if(!$setup):?><div class="authlinks"><?php if($mode==='login'):?><a href="?mode=forgot">Forgot password?</a><a href="?mode=register">Register</a><?php else:?><a href="login.php">Back to sign in</a><?php endif;?></div><?php endif;?></section></main></body></html>
